class Solution {
public:
    bool canIWin(int maxChoosableInteger, int desiredTotal) {
        if (desiredTotal <= 0) return true;
        int sum = maxChoosableInteger * (maxChoosableInteger + 1) / 2;
        if (sum < desiredTotal) return false;
        vector<char> memo(1 << maxChoosableInteger, -1);
        return dfs(0, desiredTotal, maxChoosableInteger, memo);
    }
private:
    bool dfs(int used, int remaining, int maxInt, vector<char>& memo) {
        if (memo[used] != -1) return memo[used];
        for (int i = 1; i <= maxInt; i++) {
            int bit = 1 << (i - 1);
            if (used & bit) continue;
            if (i >= remaining || !dfs(used | bit, remaining - i, maxInt, memo)) {
                return memo[used] = true;
            }
        }
        return memo[used] = false;
    }
};
